--
-- Table structure for table `detalle_venta`
--

DROP TABLE IF EXISTS `detalle_venta`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `detalle_venta` (
  `ID_Detalle` int NOT NULL,
  `ID_Venta` int NOT NULL,
  `ID_Producto` int NOT NULL,
  `Cantidad` int NOT NULL,
  `Precio_Unitario` decimal(8,2) NOT NULL,
  PRIMARY KEY (`ID_Detalle`),
  KEY `idx_detalle_venta` (`ID_Venta`),
  KEY `idx_detalle_producto` (`ID_Producto`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci
/*!50100 PARTITION BY RANGE (`ID_Detalle`)
(PARTITION p1 VALUES LESS THAN (75000) ENGINE = InnoDB,
 PARTITION p2 VALUES LESS THAN (150000) ENGINE = InnoDB,
 PARTITION p3 VALUES LESS THAN (225000) ENGINE = InnoDB,
